        UNION { VALUES ?root { wd:Q17320256 wd:Q1454986 wd:Q9357058 wd:Q155640 wd:Q25342 wd:Q39552 wd:Q131412483 wd:Q172858 wd:Q570412 wd:Q115927938 wd:Q903282 wd:Q487005 wd:Q47574 wd:Q11465 wd:Q842189 wd:Q1758425 wd:Q41364 wd:Q900231 wd:Q42213 } BIND(?root AS ?item) }
        ?item rdfs:label ?en, ?zh.
        FILTER(LANG(?en)="en" && LANG(?zh) IN ("zh-hans", "zh-cn", "zh", "zh-tw", "zh-hant"))
        FILTER NOT EXISTS { ?item wdt:P31 wd:Q5 }
